scripts.蔷薇对话.txt:
	If ($Event == $2026) @L2026;
	If ($Event == $2027) @L2027;
	If ($Event == $2021) @L2021;
	If ($Event == $2022) @L2022;
	If ($Event == $2023) @L2023;
	If ($Event == $2024) @L2024;
	If ($Event == $2025) @L2025;
	If ($Event == $2030) @L2030;
	Return;

@L2021:
	PlaySound("蔷薇哭声1.wav");
	Say("蔷薇：爹……你不能死……薇儿来看你了……呜……",32);
	Say("杨影枫：……蔷薇，你爹已经死了……，你也不要太难过。",5);
	Say("蔷薇：爹……我一定要给你报仇……呜……",32);
	Say("杨影枫：……蔷薇，你千万不要去找纳兰潜凛去送死。",5);
	Say("蔷薇：……我打不过他……不是还有你吗？",32);
	Say("杨影枫：我……我会去找纳兰潜凛做一个了断的。",5);
	Say("蔷薇：呜……纳兰潜凛是纳兰真他爹，你为了纳兰真，一定不肯杀了他的。",32);
	Say("杨影枫：我……我的内力多半是你爹传给我的，为了报答他，我会替他报仇的。",5);
	Say("蔷薇：真的吗？万一纳兰真要阻拦怎么办？如果她不让你杀死她爹呢？",32);
	Say("杨影枫：我……我……",5);
	Say("蔷薇：我就知道你舍不得她，呜……我爹死的太惨了……",32);
	Say("杨影枫：先别哭了，我们把你爹先埋葬了吧。",5);
	Say("蔷薇：嗯……",32);
	
	FadeOut();
	ClearBody();
	DelNpc("孟知秋");
	AddObj("孟知秋之墓.ini",3,50,0);
	SaveObj();
	SetPlayerPos(4,53);
	SetPlayerDir(3);
	SetNpcPos("蔷薇",5,52);	
	SetNpcDir("蔷薇",3);	
	SetNpcActionFile("蔷薇",0,"npc019_st.asf");
	SetNpcActionFile("蔷薇",1,"npc019_pst.asf");
	ChangeMapColor(100, 150, 255);
	ChangeAsfColor(150, 200, 255);
	FadeIn();
	Say("蔷薇：爹，你安息吧……我和影枫哥会给你报仇的。",32);
	Say("杨影枫：……",5);
	Assign($Event, 2022);
	SetNpcKind("蔷薇",3);
	Return;

@L2022:
	Say("杨影枫：唉……不知道真儿现在怎么样了",5);
	Say("蔷薇：影枫哥……她和她爹在一起，不会有事的。天色已晚，我们就在这休息吧。",29);
	Say("杨影枫：嗯……，也好。",2);
	FadeOut();
	SetPlayerPos(24,21);
	SetPlayerDir(3);
	SetNpcKind("蔷薇",1);
	SetNpcPos("蔷薇",24,20);
	SetNpcDir("蔷薇",7);
	FadeIn();
	Say("杨影枫：薇儿，你就在这里休息吧，我到隔壁房间去睡。",2);
	Say("蔷薇：影枫哥……我害怕，不敢一个人睡觉，你留在这里来陪我好吗？",29);
	Say("杨影枫：嗯……这好像不太好吧……",2);
	Say("蔷薇：影枫哥……不要走……不要丢下薇儿一个人……",32);
	Choose("是否留下来陪蔷薇一起睡？","是","否",$wangwei);
	If ($wangwei == 0) @yes; // yes
	Say("杨影枫：……不行，薇儿，你还是一个人睡吧。",7);
	Say("蔷薇：……影枫哥……",32);
	PlayerGotoEx(26,36);
	Sleep(1000);
	FadeOut();
	SetPlayerPos(18,46);
	PlayerGotoEx(14,46);
	FadeIn();
	PlayerGoto(14,46);
	Say("杨影枫：真儿……你到底在哪里……",5);
	Sleep(1000);
	Say("良久……");
	Say("杨影枫：好累，我还是早点睡觉吧。",2);
	PlaySound("蔷薇叫声1.wav");
	Say("隔壁突然传来蔷薇的叫声");
	Say("杨影枫：咦！出了什么事？我快去看看。",2);
	Assign($Event, 2023);
	Return;

@L2023:
	Say("杨影枫：薇儿，你还好吧，发生了什么事？",2);
	Say("蔷薇：……影枫哥……我梦见你不要薇儿了……",32);
	Say("杨影枫：怎么会呢？我答应过你爹会照顾你的。",2);
	Say("蔷薇：……可是……我害怕……   你陪我一起睡好吗？",32);
	Choose("是否留下来陪蔷薇一起睡？","是","否",$wangwei);
	If ($wangwei == 0) @yes; // yes
	Say("杨影枫：我……你还是一个人睡吧。",3);
	Say("蔷薇：……影枫哥……",32);
	PlayerGotoEx(26,36);
	Sleep(1000);
	FadeOut();
	SetPlayerPos(18,46);
	PlayerGotoEx(14,46);
	FadeIn();
	PlayerGoto(14,46);
	Say("杨影枫：唉……其实薇儿也蛮可怜的……",2);
	Say("杨影枫：我还是早点睡觉吧。",2);
	PlaySound("蔷薇叫声1.wav");
	Say("隔壁又传来蔷薇的叫声");
	Assign($Event, 2024);
	Return;
	
@L2024:
	Say("杨影枫：薇儿，又发生了什么事？",4);
	Say("蔷薇：……我看到了一只蟑螂……",32);
	Say("杨影枫：在哪里？我帮你把它打死。",2);
	Say("蔷薇：……好像逃走了……我好害怕……影枫哥……你不要走了……",32);
	Choose("是否留下来陪蔷薇一起睡？","是","否",$wangwei);
	If ($wangwei == 0) @yes; // yes
	Say("杨影枫：……我……如果没什么事，你还是早点睡吧。",3);
	Say("蔷薇：……影枫哥……",32);
	PlayerGotoEx(26,36);
	Sleep(1000);
	FadeOut();
	SetPlayerPos(18,46);
	PlayerGotoEx(14,46);
	FadeIn();
	PlayerGoto(14,46);
	Say("杨影枫：唉……真烦……",2);
	Say("杨影枫：我要睡觉了。",2);
	PlaySound("蔷薇叫声1.wav");
	Say("隔壁又传来蔷薇的叫声");
	Say("杨影枫：又发生了什么事？",4);
	Assign($Event, 2025);
	Return;

@L2025:
	Say("杨影枫：薇儿，你又怎么了？",8);
	Say("蔷薇：……我刚才看到一个黑影从窗户外闪过……",32);
	Say("杨影枫：薇儿，你可能是悲伤过度，看花眼了吧。",2);
	Say("蔷薇：……不会的……我真的看到了……",32);
	Say("杨影枫：我想可能是鸟儿飞过吧，你放松一点好吗？",3);
	Say("蔷薇：……影枫哥……我害怕，求你和我一起睡好吗？有你在身边我就什么都不怕了。",32);
	Choose("是否留下来陪蔷薇一起睡？","是","否",$wangwei);
	If ($wangwei == 0) @yes; // yes
	Say("杨影枫：……你还是自己睡吧……",7);
	Say("蔷薇：……影枫哥……我怕在也见不到你了……",32);
	Say("杨影枫：怎么会呢？你不要再胡思乱想了好吗？",4);
	Say("蔷薇：……影枫哥……",32);
	Say("杨影枫：时间不早了……你还是赶紧睡吧。",7);
	Say("蔷薇：……影枫哥……",32);
	PlayerGotoEx(26,36);
	Sleep(1000);
	FadeOut();
	SetPlayerPos(18,46);
	PlayerGotoEx(14,46);
	FadeIn();
	PlayerGoto(14,46);
	Say("杨影枫：菩萨保佑，她不要再叫了，她再叫，我就……",5);
	Sleep(1000);
	Say("杨影枫：嗯？好像没事了，我也该睡觉了。",3);
	FadeOut();
	Sleep(2000);
	Say("良久……");
	PlaySound("蔷薇哭声1.wav");
	SetNpcKind("蔷薇",0);
	SetNpcPos("蔷薇",24,18);
	SetNpcDir("蔷薇",1);
	SetNpcRes("蔷薇","npc019-蔷薇自杀.ini");
	Say("从隔壁传来蔷薇抽泣的声音，要不要起身出去看看？");
	Choose("是否起身去隔壁看看？","是","否",$wangwei);
	If ($wangwei == 0) @dead; // yes
	Say("杨影枫：又在搞什么鬼，我睡我的，不管她了。",4);
	Sleep(1000);
	Say("一夜过去");
	SetPlayerDir(7);
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	FadeIn();
	Assign($Event, 2027);
	Return;

@dead: // 蔷薇死亡
	Say("杨影枫：唉……也罢……我还是过去看看吧。",5);
	SetPlayerDir(7);
	FadeIn();
	Assign($Event, 2026);
	Return;

@yes:	
	Say("杨影枫：嗯……好吧，薇儿。",3);
	Say("蔷薇：影枫哥……你真好……",30);
	Say("杨影枫：薇儿……我来帮你宽衣",3);
	Say("蔷薇：影枫哥……你真坏……",30);
	FadeOut();
	Say("………………");
	StopMusic();
	PlaySound("蔷薇哭声1.wav");
	Say("夜半，蔷薇忽然抽泣起来。");
	PlayMusic("mc006.mp3");
	Say("杨影枫：……薇儿，好好的为什么哭了？",3);
	Say("蔷薇：影枫哥……我……",32);
	Say("杨影枫：……薇儿，又想你爹了？",3);
	Say("蔷薇：影枫哥……不是……",32);
	Say("杨影枫：……那是为什么？",3);
	Say("蔷薇：影枫哥……我害怕……",32);
	Say("杨影枫：我这不是在你身边吗，你还怕什么？",3);
	Say("蔷薇：……我怕再也见不到你了……",32);
	Say("杨影枫：薇儿，你不用担心，我不会辜负你的。",3);
	Say("蔷薇：影枫哥……其实真儿、眉儿她们都是好女孩，你不要辜负她们才对。",32);
	Say("杨影枫：薇儿，你能这么想，真是太好了。",3);
	Say("蔷薇：影枫哥……我要是能给你生一个孩子该有多好啊。",30);
	Say("杨影枫：不好。",3);
	Say("蔷薇：为什么……",32);
	Say("杨影枫：我不要一个，我要一大堆孩子。",3);
	Say("蔷薇：哼……你当我是在孵小鸡呀……",124);
	Say("杨影枫：薇儿，别多说了，快睡吧。明天我们一起去找真儿。",3);
	Sleep(1000);
	Say("蔷薇：影枫哥……你别睡……陪我聊会儿天好吗？",32);
	Say("杨影枫：薇儿，你今晚的话好像特别多，好吧，我陪你。",3);
	Say("蔷薇：影枫哥……你对我真好……就算明天我就死了，也心满意足了。",32);
	PlaySound("蔷薇哭声1.wav");
	Say("说着，蔷薇又抽泣起来。");
	Say("杨影枫：薇儿，你怎么了？好好的哭什么。",3);
	Say("蔷薇：没有……我只是太高兴了……",30);
	Say("杨影枫：薇儿，你好像有什么事在瞒着我。",4);
	Say("蔷薇：没有……影枫哥……你不要瞎猜",30);
	Say("杨影枫：不，一定有，你快告诉我。",4);
	Say("蔷薇：我……",32);
	Sleep(1000);
	Say("蔷薇：……影枫哥……我恐怕就快要死了……",32);
	Say("杨影枫：为什么？",4);
	Say("蔷薇：在飞龙堡时，魔教的护法“黑煞瘟神”卜风想要非礼我，幸亏真儿姐姐及时赶到杀死了卜风，但是我已经中了他的剧毒，十日之内就会全身腐烂而死。",32);
	Say("杨影枫：啊！你怎么不早跟我说，你中的到底是什么毒？",4);
	Say("蔷薇：听说是一种西域奇毒，名叫：穿肠雪蛛毒……",32);
	Say("杨影枫：那卜风的身上没有解药吗？",4);
	Say("蔷薇：……没有……听说只有他妻子“玉面罗刹”司空情才有解药。",32);
	Say("杨影枫：纳兰真呢？",4);
	Say("蔷薇：她好像又和他父亲和好了，他们一起离开了飞龙堡，不知去了哪里。",32);
	Say("杨影枫：不行，我们现在就去找解药。",6);
	Say("蔷薇：不要啊……影枫哥……我只要你这样静静的陪着我。",32);
	Say("杨影枫：薇儿……唉……",5);
	Say("………………");
	Say("蔷薇：影枫哥……还记得当初我们是怎么认识的吗？",30);
	Say("杨影枫：记得……你的发钗……还有那该死的杀人鱼……",2);
	Say("蔷薇：影枫哥……我给你的发钗还在吗？",30);
	Say("杨影枫：在……你看……",3);
	Say("………………");
	StopMusic();
	Say("一夜过去");
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	FullLife();
	FullThew();
	FullMana();
	AddThew(-500);
	FadeIn();
	Say("杨影枫：薇儿，我带你去药王谷找胡神医，说不定他有办法救你。",2);
	Say("蔷薇：影枫哥……只要能和你在一起，去哪里都行。",29);
	Say("杨影枫：那好，我们出发吧。",2);
	SetNpcKind("蔷薇",3);
	SetNpcDeathScript("蔷薇","主角死亡.txt");
	SetMapTrap(1,"trap01.txt");
	PlayerGotoEx(26,36);
	Sleep(1000);
	FadeOut();
	Say("经过几日的长途跋涉，二人来到了药王谷。");
	LoadMap("map_063_药王谷.map");
	LoadNpc("yaowanggu.npc");
	LoadObj("yaowanggu.obj");
	SetPlayerPos(52,24);
	FadeIn();
	PlayMusic("mc013.mp3");
	Watch("杨影枫","蔷薇",0);	
	Say("杨影枫：薇儿，你累吗？",2);
	Say("蔷薇：影枫哥……我不累……",29);
	Say("杨影枫：薇儿，胡神医曾经救过紫轩，他一定会有办法救你的。",2);
	Say("蔷薇：影枫哥……我听说胡神医救人不收钱财，但要给他一件稀世宝物……而我们……",29);
	Say("杨影枫：薇儿，你放心，无论他要什么样的宝物，我都会想办法取来的。",2);
	Assign($Event, 2030);
	SetMapTrap(1,"");
	Return;

@L2030:
	Say("杨影枫：薇儿，胡神医一定有办法救你。",2);
	Say("蔷薇：影枫哥……只要和你在一起……就算我死了也……",32);
	Return;

@L2026:
	StopMusic();
	Say("蔷薇用刀刺进了自己的小腹");
	PlayMusic("mc008.mp3");
	PlayerGoto(24,19);
	SetPlayerDir(3);
	Say("杨影枫：薇儿！你为什么要自杀？",4);
	Say("蔷薇：影枫哥……我……我……",32);
	Say("杨影枫：薇儿！你坚强些，我来救你。",5);
	Say("蔷薇：影枫哥……不要……你抱抱我好吗？",32);
	Say("杨影枫：……好……",5);
	NpcSpecialAction("杨影枫","mpc蔷葳死-3.asf");
	Sleep(1000);
	DelNpc("蔷薇");
	Sleep(1000);
	SetNpcActionFile("杨影枫",0,"mpc蔷葳死-5.asf");
	SetNpcActionFile("杨影枫",1,"mpc蔷葳死-5.asf");
	Sleep(1000);
	Say("蔷薇：影枫哥……你坐下来好吗？",32);
	Say("杨影枫：……好……",5);
	FadeOut();	
	SetPlayerPos(24,18);
	SetNpcRes("杨影枫","npc007-杨影枫蔷薇1.ini");
	FadeIn();
	Say("杨影枫：薇儿！你为什么要自杀？",4);
	Say("蔷薇：影枫哥……其实我已经活不长了……",32);
	Say("杨影枫：为什么？",4);
	Say("蔷薇：……我中了魔教妖人的剧毒……不出十日就会全身腐烂而死……",32);
	Say("杨影枫：为什么？你为什么不早告诉我？",4);
	Say("蔷薇：……影枫哥……你别怪我……好吗？",32);
	Say("杨影枫：好，我不怪你，但是你为什么这么傻？",5);
	Say("蔷薇：……影枫哥……你喜欢我吗？",32);
	Say("杨影枫：我……喜欢……",5);
	Say("蔷薇：……影枫哥……能死在你的怀里，我已经心满意足了……",32);
	Say("杨影枫：薇儿……你不要死，我带你去看医生……",5);
	Say("蔷薇：……影枫哥……",32);
	Say("蔷薇含笑而终……");
	Say("杨影枫大叫：薇儿……",5);
	StopMusic();
	FadeOut();
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	AddObj("孟知秋之墓.ini",4,48,0);
	SaveObj();
	SetNpcRes("杨影枫","npc007-杨影枫2.ini");
	SetPlayerPos(5,51);
	SetPlayerDir(3);
	FadeIn();
	Say("杨影枫：薇儿……我一定要给你报仇！",6);
	SetMapTrap(1,"trap01.txt");
	Assign($Event, 2100);
	PlayMusic("mc014.mp3");
	Return;

@L2027:
	Say("杨影枫：薇儿！",4);
	Say("蔷薇用刀刺进了自己的小腹，已经死去多时了。");
	Say("杨影枫：薇儿！这是为什么？你为什么要自杀？",4);
	StopMusic();
	FadeOut();
	Say("杨影枫埋葬了蔷薇的尸体");
	DelNpc("蔷薇");
	SaveNpc();
	AddObj("孟知秋之墓.ini",4,48,0);
	SaveObj();
	SetPlayerPos(5,51);
	SetPlayerDir(3);
	FadeIn();
	Say("杨影枫：薇儿……你为什么要自杀？",5);
	SetMapTrap(1,"trap01.txt");
	Assign($Event, 2100);
	PlayMusic("mc014.mp3");
	Return;

scripts.孟知秋对话.txt:
	GetRandNum($MengTalk, 1, 4);
	If ($MengTalk == 1) @MengTalk31;
	If ($MengTalk == 2) @MengTalk32;
	If ($MengTalk == 3) @MengTalk33;
	If ($MengTalk == 4) @MengTalk34;
	
@MengTalk31:
	Say("孟知秋：影枫，武当山的事怎么样了？", 42);
	Say("杨影枫：我这就去武当山。", 2);
	Goto @end;
@MengTalk32:
	Say("孟知秋：影枫，无忧教来势不小，你此去武当山，千万小心。", 42);
	Say("杨影枫：多谢前辈关心，晚辈一定注意。", 2);
	Goto @end;
@MengTalk33:
	Say("孟知秋：影枫，武当山事情紧急，你要抓紧时间。", 42);
	Say("杨影枫：晚辈这就赶去。", 2);
	Goto @end;
@MengTalk34:
	Talk(80740, 80750);
	Goto @end;
@end:
	Return;

scripts.李总管对话.txt:
	GetRandNum($TalkFight, 1, 2);
	If ($TalkFight == 1) @TalkFight31;
	If ($TalkFight == 2) @TalkFight32;
	
	@TalkFight31:
		Talk(80880, 80880);
		Goto @end;
	@TalkFight32:
		Say("李总管：公子，我们落叶谷家丁都训练有素，说明我平时的工作还是卓有成效的，谷主应该给我加点儿薪啊。", 74);
		Goto @end;
@end:
