scripts.孟知秋临终对话.txt:
	If ($Event == 2000) @Evt2000;
	If ($Event == 2001) @Evt2001;
	If ($Event == 2002) @Evt2002;
	If ($Event == 2021) @Evt2021;
	Return;

@Evt2000:
	PlayerGoto(18,96);
	SetPlayerDir(5);
	Say("杨影枫：前辈……怎么会这样？",4);
	Say("孟知秋：魔教教主纳兰潜凛……他想要称霸中原武林，自然不肯放过我……",43);
	Say("孟知秋：蔷薇呢……她不是和你在一起吗？",43);
	Say("杨影枫：薇儿她……被魔教的人抓走了。",7);
	Say("杨影枫：唉……我真没用。",7);
	Sleep(1000);
	Say("孟知秋：……你转过身去……",42);
	Say("杨影枫：前辈……",7);
	Say("孟知秋：以你现在的功力，还不是纳兰潜凛的敌手，我要传功给你。",42);
	Say("杨影枫：前辈……万万不可……",4);
	Say("孟知秋：我已经活不长了……，但薇儿她还小，我死之后，她便再无亲人，希望你能好好照顾她。",42);
	Say("杨影枫：前辈你放心，我一定会的。",5);
//	SetPlayerDir(1);
//	Sleep(1000);
	FadeOut();
	ShowNpc("杨影枫",0);
	NpcSpecialAction("孟知秋","mpc169-1.asf");
	FadeIn();
	Sleep(9000);
	FadeOut();
	ShowNpc("杨影枫",1);
	SetPlayerDir(5);
	Say("良久……");
	Sleep(2000);
	AddExp(100000);
	SetNpcAction("孟知秋",0);
	FadeIn();
	Say("杨影枫：前辈，你还好吧。",5);
	Say("孟知秋：咳……咳……",42);
	Say("杨影枫：前辈，你不会有事的。",5);
	Say("孟知秋：魔教的老巢在倚天山摘星楼，薇儿很可能被抓到那里了。",42);
	Say("杨影枫：前辈，我现在就去把她救回来。",5);
	Say("孟知秋：纳兰潜凛诡计多端，你千万要小心。",42);
	Say("杨影枫：我会的。",5);
	Memo("去倚天山摘星楼救蔷薇");
	Assign($Event, 2001);
	Return;

@Evt2001:
	Say("杨影枫：前辈，我走了……",4);
	Say("孟知秋：我要是能看到你和薇儿结婚就好了……",42);
	Say("杨影枫：你会的……",4);
	Say("孟知秋：咳……咳……",42);
	Return;

