	Say("孟知秋：咳……咳……找到蔷薇了吗？",42);
	Say("杨影枫：还没有。",4);
	Say("孟知秋：纳兰潜凛诡计多端，你千万要小心。",42);
	Say("杨影枫：我会的。",5);
	Return;

@Evt2021:
	Say("孟知秋已经死亡多时");
	Return;

